import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { Group, Mesh, PlaneGeometry } from 'three';
import { createText } from '@/text';
import { primitives } from '@/primitives';

export default function createNode(config, ctx) {
  const root = new Group();

  // Geometry & material
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, transparent: true });
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Text content
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: palette.paper,
      align: 'center',
    });
    // Slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // Apply cinematic primitives (none in this spec, but keep loop for safety)
  const appliedPrimitives = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (typeof ctx.primitives[prim.name] === 'function') {
        const instance = ctx.primitives[prim.name](root, prim.params);
        appliedPrimitives.push(instance);
        // trigger handling could be added here if required
      }
    }
  }

  // Handlers placeholder
  root.userData.handlers = {};

  // Cleanup
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    if (material.map) material.map.dispose();
    material.dispose();

    // Dispose any textures used by text objects
    root.traverse((obj) => {
      if (obj.isMesh && obj.material && obj.material.map) {
        obj.material.map.dispose();
        obj.material.dispose();
      }
      if (obj.geometry) obj.geometry.dispose();
    });

    // Kill GSAP timelines (none expected)
    gsap.globalTimeline.clear();

    // Cleanup applied primitives
    for (const inst of appliedPrimitives) {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    }
  };

  return root;
}
